def forward(groups):
    dt_str = groups[0] + groups[2] + groups[3]
    dt = datetime.strptime(dt_str, '%y%m%d%H%M%S')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': [len(groups[1])]}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%y%m%d') + (' ' * record['layout'][0]) + dt.strftime('%H%M%S')
